function makeFamily(s,legacy=false){
const identity=identityFor(s.origin),names=identity.slice(1);const jobsByCountry={BY:['учительница','электрик'],PT:['работница кафе','водитель'],BR:['продавец','мастер по ремонту'],JP:['медсестра','офисный сотрудник']};const jobs=jobsByCountry[s.origin.iso2]||[['учительница','медсестра','продавец','бухгалтер','повар','дизайнер'][Math.floor(rand(s)*6)],['электрик','водитель','строитель','программист','повар','мастер по ремонту'][Math.floor(rand(s)*6)]];
let wealth=legacy?(s.stats.money<35?'modest':s.stats.money<65?'steady':'wealthy'):['modest','steady','wealthy'][Math.floor(rand(s)*3)],t=rand(s),tone=t<.42?'warm':t<.72?'busy':t<.94?'reserved':'harsh';
const money={modest:24,steady:49,wealthy:78}[wealth],bond={warm:83,busy:68,reserved:53,harsh:42}[tone];
const home={modest:'Денег немного: покупки планируют, игрушки иногда делают сами.',steady:'На привычную жизнь хватает, крупные покупки откладывают заранее.',wealthy:'Семья может позволить просторное жильё, занятия и новые игрушки.'}[wealth];
const climate={warm:'Здесь любят обниматься, разговаривать и собираться за одним столом.',busy:'Родители часто заняты. Они стараются быть рядом, но иногда возвращаются, когда вы уже спите.',reserved:'Взрослые заботятся о порядке и занятиях. Обнимать и хвалить здесь привыкли нечасто.',harsh:'Дома бывает спокойно, а иногда взрослые резко срываются. Бабушка — человек, рядом с которым можно выдохнуть.'}[tone];
s.family={wealth,tone,home,climate,mother:{name:names[0],job:jobs[0]},father:{name:names[1],job:jobs[1]},grandmother:{name:names[2]},safePerson:'grandmother'};
if(!legacy){s.stats.money=money;s.stats.bond=bond;s.baseline.money=money;s.baseline.bond=bond;s.origin.family=`Мама ${names[0]} — ${jobs[0]}, папа ${names[1]} — ${jobs[1]}. ${home} ${climate}`;}
}
function ensureChildhood(s){if(!s.family)makeFamily(s,true);if(!s.childhood)s.childhood={step:s.age>=6?5:0,finished:s.age>=6,traits:{curiosity:0,connection:0,imagination:0,steadiness:0},moments:[]};return s;}
